package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId       string          // PIC X(5) @0 len=5
	TrIncome   decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsIncEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                                    // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxFile *os.File
var taxReader *bufio.Scanner
var taxRec TaxRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// COBOL numeric-edited formatting: picture with Z , . 9
func formatEdited(val decimal.Decimal, picture string) string {
	width := len(picture)
	// find decimal places after '.'
	scale := 0
	if idx := strings.Index(picture, "."); idx >= 0 {
		scale = width - idx - 1
	}
	// integer digit slots: count of Z and 9 before dot
	intPartPic := picture
	if idx := strings.Index(picture, "."); idx >= 0 {
		intPartPic = picture[:idx]
	}
	intSlots := 0
	for _, c := range intPartPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// Round half away from zero to scale (COBOL ROUNDED equivalent for display moves?
	// But MOVE to edited is not ROUNDED? Actually COBOL rounds? For simplicity truncate? 
	// Values already have correct scale, so rounding not needed except overflow.
	// Use string with exactly scale decimals.
	// Ensure val is rounded to scale for display? COBOL MOVE does rounding.
	val = val.Round(int32(scale))

	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// Format with exactly scale decimal digits
	s := val.StringFixed(int32(scale)) // e.g. "1234.56"
	// split
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// pad/truncate frac
		if len(fracStr) < scale {
			fracStr += strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
	} else {
		intStr = s
	}

	// Handle overflow: keep low-order digits that fit
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// left pad intStr with zeros to intSlots for Z processing
	intStrPadded := strings.Repeat("0", intSlots-len(intStr)) + intStr

	// Build integer part with commas according to picture
	// intPartPic contains pattern like "ZZZ,ZZ9" or "ZZ,ZZZ,ZZ9"
	resultInt := make([]byte, len(intPartPic))
	// Map digit positions: iterate over intPartPic from right to left, filling digits
	digitIdx := len(intStrPadded) - 1
	for i := len(intPartPic) - 1; i >= 0; i-- {
		ch := intPartPic[i]
		if ch == ',' {
			resultInt[i] = ','
		} else { // Z or 9
			resultInt[i] = intStrPadded[digitIdx]
			digitIdx--
		}
	}
	// Apply Z suppression: leading zeros become spaces, commas in suppressed zone become spaces
	// Z means suppress; 9 means always show.
	// Suppression goes until first non-zero digit in Z region, or up to last Z.
	for i := 0; i < len(intPartPic); i++ {
		ch := intPartPic[i]
		if ch == 'Z' {
			if resultInt[i] == '0' {
				resultInt[i] = ' '
			} else {
				break
			}
		} else if ch == ',' {
			if resultInt[i] == ',' {
				// check if all to left are spaces (still suppressed)
				// If we replaced leading zeros with spaces, comma should be space if still in suppressed zone
				// Determine if any non-space non-comma non-zero remains to left? Simpler: if all digits to left in resultInt are spaces
				allSpace := true
				for k := 0; k < i; k++ {
					if resultInt[k] != ' ' && resultInt[k] != ',' {
						allSpace = false
						break
					}
					if resultInt[k] != ' ' {
						// comma already counted
					}
				}
				// Actually check if we have not yet hit a non-zero digit: if previous Z's are all spaces, this comma is in suppressed zone
				suppressed := true
				for k := 0; k < i; k++ {
					if intPartPic[k] == 'Z' || intPartPic[k] == '9' {
						if resultInt[k] != ' ' {
							suppressed = false
							break
						}
					} else if intPartPic[k] == ',' {
						if resultInt[k] != ' ' {
							suppressed = false
							break
						}
					}
				}
				_ = allSpace
				if suppressed {
					resultInt[i] = ' '
				}
			}
		} else if ch == '9' {
			break
		}
	}
	// Handle case where integer is zero: need at least one zero before decimal
	// With ZZZ,ZZ9 pattern, the '9' ensures one zero remains, already handled.

	intPartStr := string(resultInt)
	if scale > 0 {
		return intPartStr + "." + fracStr
	}
	return intPartStr
}

func storeWsTax(v decimal.Decimal) {
	// PIC 9(7)V99: scale 2, integer 7 digits
	v = v.Round(2)
	// truncate high-order: keep low 7 integer digits
	// Use string manipulation
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	s := v.StringFixed(2) // "12345.67"
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	frac := ""
	if len(parts) > 1 {
		frac = parts[1]
	}
	if len(intStr) > 7 {
		intStr = intStr[len(intStr)-7:]
	}
	// rebuild
	combined := intStr + "." + frac
	d, _ := decimal.NewFromString(combined)
	if neg {
		d = d.Neg()
	}
	WsTax = d
}

func storeWsNet(v decimal.Decimal) {
	v = v.Truncate(2)
	s := v.StringFixed(2)
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	neg := false
	if strings.HasPrefix(intStr, "-") {
		neg = true
		intStr = intStr[1:]
	}
	if len(intStr) > 7 {
		intStr = intStr[len(intStr)-7:]
	}
	frac := ""
	if len(parts) > 1 {
		frac = parts[1]
	}
	combined := intStr + "." + frac
	d, _ := decimal.NewFromString(combined)
	if neg {
		d = d.Neg()
	}
	WsNet = d
}

func storeWsTotalTax(v decimal.Decimal) {
	v = v.Truncate(2)
	s := v.StringFixed(2)
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	neg := false
	if strings.HasPrefix(intStr, "-") {
		neg = true
		intStr = intStr[1:]
	}
	if len(intStr) > 9 {
		intStr = intStr[len(intStr)-9:]
	}
	frac := ""
	if len(parts) > 1 {
		frac = parts[1]
	}
	combined := intStr + "." + frac
	d, _ := decimal.NewFromString(combined)
	if neg {
		d = d.Neg()
	}
	WsTotalTax = d
}

func parseIncome(raw string) decimal.Decimal {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return decimal.Zero
	}
	// raw is digits only, 8 chars
	// implied 2 decimals
	d, _ := decimal.NewFromString(raw)
	// shift -2
	return d.Shift(-2)
}

func mainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer taxFile.Close()
	taxReader = bufio.NewScanner(taxFile)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	taxReader.Buffer(buf, 1024*1024)

	readPara()
	for !isInputDone() {
		processPara()
	}
	taxFile.Close()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) -> zero padded? But in DISPLAY, numeric fields are...
	// For unedited numeric DISPLAY, rule says zero-padded to digit count. However COBOL DISPLAY of numeric item often shows as is.
	// We'll format as integer without padding? Check spec: "An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count."
	// So WS-COUNT should be 3 digits zero-padded.
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func readPara() {
	if !taxReader.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := taxReader.Text()
	// Pad with spaces to 13
	if len(line) < 13 {
		line += strings.Repeat(" ", 13-len(line))
	}
	if len(line) > 13 {
		line = line[:13]
	}
	taxRec.TrId = line[0:5]
	rawInc := line[5 : 5+8]
	taxRec.TrIncome = parseIncome(rawInc)
}

func processPara() {
	hundred00 := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)

	if taxRec.TrIncome.Cmp(decimal.NewFromInt(10000)) <= 0 {
		v := taxRec.TrIncome.Mul(rate10)
		v = v.Round(2)
		storeWsTax(v)
	} else {
		if taxRec.TrIncome.Cmp(fortyThousand) <= 0 {
			diff := taxRec.TrIncome.Sub(hundred00)
			v := diff.Mul(rate20).Add(thousand)
			v = v.Round(2)
			storeWsTax(v)
		} else {
			diff := taxRec.TrIncome.Sub(fortyThousand)
			v := diff.Mul(rate30).Add(sevenThousand)
			v = v.Round(2)
			storeWsTax(v)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (no ROUNDED => truncate)
	wsnetVal := taxRec.TrIncome.Sub(WsTax)
	storeWsNet(wsnetVal)

	// ADD WS-TAX TO WS-TOTAL-TAX
	storeWsTotalTax(WsTotalTax.Add(WsTax))
	WsCount++

	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	readPara()
}

func main() {
	mainPara()
}
